package com.solarmind.security; import com.solarmind.config.JwtProperties; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.util.Date; import javax.crypto.SecretKey;
@Component public class JwtUtil { private final JwtProperties p; public JwtUtil(JwtProperties p){this.p=p;} private SecretKey key(){return Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));} public String issue(String subject){Date now=new Date();return Jwts.builder().subject(subject).issuedAt(now).expiration(new Date(now.getTime()+p.expirationMs())).signWith(key()).compact();} public String subject(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{subject(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
